30	template <
31	    typename AlgTopoMatch, typename InsAlgTemplate0, typename InsAlgTemplate1, typename InsAlgTemplate2,
32	    typename InsAlgTemplate3>
33	std::vector<CostModelParam>
34	InsAllReduceParallelExecutor<AlgTopoMatch, InsAlgTemplate0, InsAlgTemplate1, InsAlgTemplate2, InsAlgTemplate3>::
35	    CalcCostCoeff(HcclComm comm, TopoInfoWithNetLayerDetails* topoInfo, const char* algName)
36	{
37	    (void)comm;
38	    (void)algName;
39	    u32 rankSize = topoInfo->userRankSize;
40	    auto rs = CostModelManager::Global()->CalcRankSizeByTopo(topoInfo);
41	    u32 rankSizeLevel0 = rs.level0;
42	    u32 rankSizeLevel1 = rs.level1;
43	    HCCL_INFO(
44	        "[CalcCostCoeff]rankSizeLevel0:%d, rankSizeLevel1:%d, rankSize:%d", rankSizeLevel0, rankSizeLevel1, rankSize);
45	    std::vector<CostModelParam> params = [rankSize, rankSizeLevel0, rankSizeLevel1, algName] {
46	        std::vector<CostModelParam> v;
47	        auto p0 = InsAlgTemplate0::CalcCostCoeff(
48	            CalcCostCoeffParam{rankSizeLevel0, 1.0f / 2 / rankSizeLevel0, AlgNetType::MESH, true, algName});
49	        v.insert(v.end(), p0.begin(), p0.end());
50	        auto p1 = InsAlgTemplate1::CalcCostCoeff(
51	            CalcCostCoeffParam{rankSizeLevel1, 1.0f / 2 / rankSizeLevel1, AlgNetType::CLOS, true, algName});
52	        v.insert(v.end(), p1.begin(), p1.end());
53	        auto p2 = InsAlgTemplate0::CalcCostCoeff(
54	            CalcCostCoeffParam{rankSizeLevel0, 1.0f / 2 / rankSize, AlgNetType::MESH, false, algName});
55	        v.insert(v.end(), p2.begin(), p2.end());
56	        auto p3 = InsAlgTemplate1::CalcCostCoeff(
57	            CalcCostCoeffParam{rankSizeLevel1, 1.0f / 2 / rankSize, AlgNetType::CLOS, false, algName});
58	        v.insert(v.end(), p3.begin(), p3.end());
59	        auto p4 = InsAlgTemplate2::CalcCostCoeff(
60	            CalcCostCoeffParam{rankSizeLevel0, 1.0f / 2 / rankSize, AlgNetType::MESH, false, algName});
61	        v.insert(v.end(), p4.begin(), p4.end());
62	        auto p5 = InsAlgTemplate3::CalcCostCoeff(
63	            CalcCostCoeffParam{rankSizeLevel1, 1.0f / 2 / rankSize, AlgNetType::CLOS, false, algName});
64	        v.insert(v.end(), p5.begin(), p5.end());
65	        auto p6 = InsAlgTemplate2::CalcCostCoeff(
66	            CalcCostCoeffParam{rankSizeLevel0, 1.0f / 2 / rankSizeLevel0, AlgNetType::MESH, false, algName});
67	        v.insert(v.end(), p6.begin(), p6.end());
68	        auto p7 = InsAlgTemplate3::CalcCostCoeff(
69	            CalcCostCoeffParam{rankSizeLevel1, 1.0f / 2 / rankSizeLevel1, AlgNetType::CLOS, false, algName});
70	        v.insert(v.end(), p7.begin(), p7.end());
71	        return v;
72	    }();
73	    return params;
74	}
