119	template <
120	    typename AlgTopoMatch, typename InsAlgTemplate0, typename InsAlgTemplate1, typename InsAlgTemplate2,
121	    typename InsAlgTemplate3>
122	HcclResult
123	InsAllReduceParallelExecutor<AlgTopoMatch, InsAlgTemplate0, InsAlgTemplate1, InsAlgTemplate2, InsAlgTemplate3>::CalcRes(
124	    HcclComm comm, const OpParam& param, const TopoInfoWithNetLayerDetails* topoInfo,
125	    const AlgHierarchyInfoForAllLevel& algHierarchyInfo, AlgResourceRequest& resourceRequest)
126	{
127	    if (algHierarchyInfo.infos.empty()) {
128	        HCCL_ERROR("[%s] algHierarchyInfo.infos is empty.", __func__);
129	        return HcclResult::HCCL_E_PARA;
130	    }
131	    myRank_ = topoInfo->userRank;
132	    HCCL_INFO("[InsAllReduceParallelExecutor] CalcRes start, rank[%d]", myRank_);
133	
134	    std::vector<std::vector<u32>> temp0HierarchyInfo;
135	    std::vector<std::vector<u32>> temp1HierarchyInfo;
136	    if (topoInfo->level0Topo == Level0Shape::MESH_1D_CLOS && !topoInfo->level0PcieMix) {
137	        if (algHierarchyInfo.infos[0].size() < 2) {
138	            HCCL_ERROR(
139	                "[%s] algHierarchyInfo.infos[0] size[%zu] is less than 2.", __func__, algHierarchyInfo.infos[0].size());
140	            return HcclResult::HCCL_E_PARA;
141	        }
142	        temp0HierarchyInfo = {algHierarchyInfo.infos[0][0]};
143	        std::vector<u32> closRanks;
144	        u32 meshSize = algHierarchyInfo.infos[0][0].size();
145	        for (auto rank : algHierarchyInfo.infos[0][1]) {
146	            if (rank % meshSize == topoInfo->userRank % meshSize) {
147	                closRanks.push_back(rank);
148	            }
149	        }
150	        temp1HierarchyInfo = {closRanks};
151	    } else {
152	        temp0HierarchyInfo = algHierarchyInfo.infos[0];
153	        temp1HierarchyInfo = algHierarchyInfo.infos[1];
154	    }
155	    // 实例化算法模板类
156	    // 构建template
157	    std::shared_ptr<InsAlgTemplate0> algTemplate0
158	        = std::make_shared<InsAlgTemplate0>(param, topoInfo->userRank, temp0HierarchyInfo); // RS 框内
159	    std::shared_ptr<InsAlgTemplate1> algTemplate1
160	        = std::make_shared<InsAlgTemplate1>(param, topoInfo->userRank, temp1HierarchyInfo); // RS 框间
161	    std::shared_ptr<InsAlgTemplate2> algTemplate2
162	        = std::make_shared<InsAlgTemplate2>(param, topoInfo->userRank, temp0HierarchyInfo); // AG 框内
163	    std::shared_ptr<InsAlgTemplate3> algTemplate3
164	        = std::make_shared<InsAlgTemplate3>(param, topoInfo->userRank, temp1HierarchyInfo); // AG 框间
165	
166	    // 计算资源
167	    AlgResourceRequest intraTempRequest;
168	    AlgResourceRequest interTempRequest;
169	    AlgResourceRequest intraTempRequest1;
170	    AlgResourceRequest interTempRequest1;
171	    AlgResourceRequest intraTempRequestFinal;
172	    AlgResourceRequest interTempRequestFinal;
173	
174	    CHK_RET(algTemplate0->CalcRes(comm, param, topoInfo, intraTempRequest));
175	    CHK_RET(algTemplate1->CalcRes(comm, param, topoInfo, interTempRequest));
176	    CHK_RET(algTemplate2->CalcRes(comm, param, topoInfo, intraTempRequest1));
177	    CHK_RET(algTemplate3->CalcRes(comm, param, topoInfo, interTempRequest1));
178	
179	    for (auto& KernelInfo : intraTempRequest.ccuKernelInfos) {
180	        KernelInfo.resGroup = 0;
181	    }
182	    for (auto& KernelInfo : interTempRequest.ccuKernelInfos) {
183	        KernelInfo.resGroup = 0;
184	    }
185	    for (auto& KernelInfo : intraTempRequest1.ccuKernelInfos) {
186	        KernelInfo.resGroup = 1;
187	    }
188	    for (auto& KernelInfo : interTempRequest1.ccuKernelInfos) {
189	        KernelInfo.resGroup = 1;
190	    }
191	
192	    u32 slaveThreadNumIntra = intraTempRequest.slaveThreadNum;
193	    if (intraTempRequest.slaveThreadNum >= intraTempRequest1.slaveThreadNum) {
194	        intraTempRequestFinal.notifyNumPerThread = intraTempRequest.notifyNumPerThread;
195	    } else {
196	        slaveThreadNumIntra = intraTempRequest1.slaveThreadNum;
197	        intraTempRequestFinal.notifyNumPerThread = intraTempRequest1.notifyNumPerThread;
198	    }
199	    u32 slaveThreadNumInter = interTempRequest.slaveThreadNum;
200	    if (interTempRequest.slaveThreadNum >= interTempRequest1.slaveThreadNum) {
201	        interTempRequestFinal.notifyNumPerThread = interTempRequest.notifyNumPerThread;
202	    } else {
203	        slaveThreadNumInter = interTempRequest1.slaveThreadNum;
204	        interTempRequestFinal.notifyNumPerThread = interTempRequest1.notifyNumPerThread;
205	    }
206	
207	    resourceRequest.notifyNumOnMainThread = 2; // allreduce用于两个template间同步
208	    resourceRequest.slaveThreadNum = slaveThreadNumIntra + slaveThreadNumInter + 4;
209	    resourceRequest.notifyNumPerThread.emplace_back(intraTempRequest.notifyNumOnMainThread + 1);
210	    resourceRequest.notifyNumPerThread.emplace_back(intraTempRequest1.notifyNumOnMainThread + 1);
211	    resourceRequest.notifyNumPerThread.insert(
212	        resourceRequest.notifyNumPerThread.end(), intraTempRequestFinal.notifyNumPerThread.begin(),
213	        intraTempRequestFinal.notifyNumPerThread.end());
214	    resourceRequest.notifyNumPerThread.emplace_back(interTempRequest.notifyNumOnMainThread + 1);
215	    resourceRequest.notifyNumPerThread.emplace_back(interTempRequest1.notifyNumOnMainThread + 1);
216	    resourceRequest.notifyNumPerThread.insert(
217	        resourceRequest.notifyNumPerThread.end(), interTempRequestFinal.notifyNumPerThread.begin(),
218	        interTempRequestFinal.notifyNumPerThread.end());
219	
220	    if (param.engine != COMM_ENGINE_CCU) {
221	        resourceRequest.channels.emplace_back(intraTempRequest.channels[0]);
222	        resourceRequest.channels.emplace_back(interTempRequest.channels[0]);
223	    } else {
224	        // ccu reduce scatter
225	        HCCL_INFO(
226	            "[InsAllReduceParallelExecutor][CalcRes] intraTemplate has [%d] kernels.",
227	            intraTempRequest.ccuKernelNum[0]);
228	        resourceRequest.ccuKernelInfos.insert(
229	            resourceRequest.ccuKernelInfos.end(), intraTempRequest.ccuKernelInfos.begin(),
230	            intraTempRequest.ccuKernelInfos.end());
231	        resourceRequest.ccuKernelNum.emplace_back(intraTempRequest.ccuKernelNum[0]);
232	        HCCL_INFO(
233	            "[InsAllReduceParallelExecutor][CalcRes] interTemplate has [%d] kernels.",
234	            interTempRequest.ccuKernelNum[0]);
235	        resourceRequest.ccuKernelInfos.insert(
236	            resourceRequest.ccuKernelInfos.end(), interTempRequest.ccuKernelInfos.begin(),
237	            interTempRequest.ccuKernelInfos.end());
238	        resourceRequest.ccuKernelNum.emplace_back(interTempRequest.ccuKernelNum[0]);
239	        // // ccu allgather
240	        HCCL_INFO(
241	            "[InsAllReduceParallelExecutor][CalcRes] intraTemplate1 has [%d] kernels.",
242	            intraTempRequest.ccuKernelNum[0]);
243	        resourceRequest.ccuKernelInfos.insert(
244	            resourceRequest.ccuKernelInfos.end(), intraTempRequest1.ccuKernelInfos.begin(),
245	            intraTempRequest1.ccuKernelInfos.end());
246	        resourceRequest.ccuKernelNum.emplace_back(intraTempRequest1.ccuKernelNum[0]);
247	        HCCL_INFO(
248	            "[InsAllReduceParallelExecutor][CalcRes] interTemplate1 has [%d] kernels.",
249	            interTempRequest.ccuKernelNum[0]);
250	        resourceRequest.ccuKernelInfos.insert(
251	            resourceRequest.ccuKernelInfos.end(), interTempRequest1.ccuKernelInfos.begin(),
252	            interTempRequest1.ccuKernelInfos.end());
253	        resourceRequest.ccuKernelNum.emplace_back(interTempRequest1.ccuKernelNum[0]);
254	        resourceRequest.dieSplitRatio = interTempRequest1.dieSplitRatio;
255	    }
256	
257	    HCCL_DEBUG(
258	        "[InsAllReduceParallelExecutor][CalcRes] myRank[%u], notifyNumOnMainThread[%u], slaveThreadNum[%u], "
259	        "channels[%u]",
260	        myRank_, resourceRequest.notifyNumOnMainThread, resourceRequest.slaveThreadNum,
261	        resourceRequest.channels.size());
262	    for (auto i = 0; i < resourceRequest.notifyNumPerThread.size(); i++) {
263	        HCCL_DEBUG(
264	            "[InsAllReduceParallelExecutor][CalcRes] myRank[%u], notifyNumPerThread[%u]=[%u]", myRank_, i,
265	            resourceRequest.notifyNumPerThread[i]);
266	    }
267	
268	    return HcclResult::HCCL_SUCCESS;
269	}
