271	#ifndef AICPU_COMPILE
272	template <
273	    typename AlgTopoMatch, typename InsAlgTemplate0, typename InsAlgTemplate1, typename InsAlgTemplate2,
274	    typename InsAlgTemplate3>
275	HcclResult
276	InsAllReduceParallelExecutor<AlgTopoMatch, InsAlgTemplate0, InsAlgTemplate1, InsAlgTemplate2, InsAlgTemplate3>::
277	    FastLaunchSaveCtx(
278	        const OpParam& param, const TemplateResource& templateAlgResIntra, const TemplateResource& templateAlgResInter,
279	        const TemplateResource& templateAlgResIntra1, const TemplateResource& templateAlgResInter1,
280	        u32 notifyNumOnMainThread)
281	{
282	    HCCL_INFO("[InsAllReduceParallelExecutor] loopTimes==1, save fast launch ctx.");
283	    u32 threadNum = threads_.size();
284	    u32 ccuKernelNum = ccuKernelLaunchNumIntra1_ + ccuKernelLaunchNumInter0_ + ccuKernelLaunchNumIntra0_
285	                       + ccuKernelLaunchNumInter1_ + ccuKernelLaunchNumIntra11_ + ccuKernelLaunchNumInter00_
286	                       + ccuKernelLaunchNumIntra00_ + ccuKernelLaunchNumInter11_;
287	    if (ccuKernelNum < 1) {
288	        HCCL_INFO("[InsAllReduceParallelExecutor] ccu kernel num is 0, no need to save.");
289	        return HCCL_SUCCESS;
290	    }
291	    HCCL_INFO(
292	        "[InsAllReduceParallelExecutor][HcclEngineCtxCreate] threadNum[%llu], ccuKernelNum[%llu]", threadNum,
293	        ccuKernelNum);
294	
295	    u64 size = CcuFastLaunchCtx::GetCtxSize(threadNum, ccuKernelNum);
296	    // 申请ctx
297	    void* ctxPtr = nullptr;
298	    HCCL_INFO("[InsAllReduceParallelExecutor][HcclEngineCtxCreate] Tag[%s], size[%llu]", param.fastLaunchTag, size);
299	    CHK_RET(HcclEngineCtxCreate(param.hcclComm, param.fastLaunchTag, CommEngine::COMM_ENGINE_CCU, size, &ctxPtr));
300	
301	    CcuFastLaunchCtx* ccuFastLaunchCtx = reinterpret_cast<CcuFastLaunchCtx*>(ctxPtr);
302	    // 1 算法名
303	    CHK_SAFETY_FUNC_RET(strcpy_s(ccuFastLaunchCtx->algName, sizeof(ccuFastLaunchCtx->algName), param.algName));
304	    HCCL_INFO("[InsAllReduceParallelExecutor][FastLaunchSaveCtx] algName[%s]", ccuFastLaunchCtx->algName);
305	
306	    // 2 thread
307	    ccuFastLaunchCtx->threadNum = threadNum;
308	    ccuFastLaunchCtx->notifyNumOnMainThread = notifyNumOnMainThread;
309	    ThreadHandle* threads = ccuFastLaunchCtx->GetThreadHandlePtr();
310	    for (u32 i = 0; i < threadNum; i++) {
311	        threads[i] = threads_[i];
312	    }
313	
314	    // 3 ccu kernel handle, taskArg入参
315	    u32 templateIdx = 0;
316	    ccuFastLaunchCtx->ccuKernelNum[templateIdx++] = ccuKernelLaunchNumIntra0_;
317	    ccuFastLaunchCtx->ccuKernelNum[templateIdx++] = ccuKernelLaunchNumInter1_;
318	    ccuFastLaunchCtx->ccuKernelNum[templateIdx++] = ccuKernelLaunchNumInter0_;
319	    ccuFastLaunchCtx->ccuKernelNum[templateIdx++] = ccuKernelLaunchNumIntra1_;
320	    ccuFastLaunchCtx->ccuKernelNum[templateIdx++] = ccuKernelLaunchNumInter00_;
321	    ccuFastLaunchCtx->ccuKernelNum[templateIdx++] = ccuKernelLaunchNumIntra11_;
322	    ccuFastLaunchCtx->ccuKernelNum[templateIdx++] = ccuKernelLaunchNumIntra00_;
323	    ccuFastLaunchCtx->ccuKernelNum[templateIdx++] = ccuKernelLaunchNumInter11_;
324	    CcuKernelSubmitInfo* kernelSubmitInfos = ccuFastLaunchCtx->GetCcuKernelSubmitInfoPtr();
325	
326	    for (u32 i = 0; i < threadNum; i++) {
327	        threads[i] = threads_[i];
328	    }
329	    u32 kernelIdx = 0;
330	    for (u32 i = 0; i < ccuKernelLaunchNumIntra0_; i++) {
331	        kernelSubmitInfos[kernelIdx++] = templateAlgResIntra.submitInfos[i];
332	    }
333	    for (u32 i = 0; i < ccuKernelLaunchNumInter1_; i++) {
334	        kernelSubmitInfos[kernelIdx++] = templateAlgResInter.submitInfos[i];
335	    }
336	    for (u32 i = ccuKernelLaunchNumInter1_; i < ccuKernelLaunchNumInter0_ + ccuKernelLaunchNumInter1_; i++) {
337	        kernelSubmitInfos[kernelIdx++] = templateAlgResInter.submitInfos[i];
338	    }
339	    for (u32 i = ccuKernelLaunchNumIntra0_; i < ccuKernelLaunchNumIntra1_ + ccuKernelLaunchNumIntra0_; i++) {
340	        kernelSubmitInfos[kernelIdx++] = templateAlgResIntra.submitInfos[i];
341	    }
342	    for (u32 i = 0; i < ccuKernelLaunchNumInter00_; i++) {
343	        kernelSubmitInfos[kernelIdx++] = templateAlgResInter1.submitInfos[i];
344	    }
345	    for (u32 i = 0; i < ccuKernelLaunchNumIntra11_; i++) {
346	        kernelSubmitInfos[kernelIdx++] = templateAlgResIntra1.submitInfos[i];
347	    }
348	    for (u32 i = ccuKernelLaunchNumIntra11_; i < ccuKernelLaunchNumIntra11_ + ccuKernelLaunchNumIntra00_; i++) {
349	        kernelSubmitInfos[kernelIdx++] = templateAlgResIntra1.submitInfos[i];
350	    }
351	    for (u32 i = ccuKernelLaunchNumInter00_; i < ccuKernelLaunchNumInter00_ + ccuKernelLaunchNumInter11_; i++) {
352	        kernelSubmitInfos[kernelIdx++] = templateAlgResInter1.submitInfos[i];
353	    }
354	    return HCCL_SUCCESS;
355	}
