464	template <
465	    typename AlgTopoMatch, typename InsAlgTemplate0, typename InsAlgTemplate1, typename InsAlgTemplate2,
466	    typename InsAlgTemplate3>
467	HcclResult
468	InsAllReduceParallelExecutor<AlgTopoMatch, InsAlgTemplate0, InsAlgTemplate1, InsAlgTemplate2, InsAlgTemplate3>::
469	    Orchestrate(const OpParam& param, const AlgResourceCtxSerializable& resCtx)
470	{
471	    if (resCtx.algHierarchyInfo.infos.empty()) {
472	        HCCL_ERROR("[%s] algHierarchyInfo.infos is empty.", __func__);
473	        return HcclResult::HCCL_E_PARA;
474	    }
475	    HCCL_INFO("[InsAllReduceParallelExecutor][Orchestrate] Orchestrate Start");
476	
477	    maxTmpMemSize_ = resCtx.cclMem.size;
478	    myRank_ = resCtx.topoInfo.userRank;
479	    // 给channels_和threads_赋值
480	    threads_ = resCtx.threads;
481	    HCCL_INFO("[InsAllReduceParallelExecutor][Orchestrate] threads_size[%d]", threads_.size());
482	    if (param.engine != CommEngine::COMM_ENGINE_AIV && param.engine != CommEngine::COMM_ENGINE_CCU) {
483	        CHK_RET(RestoreChannelMap(resCtx, remoteRankToChannelInfo_));
484	        intraLinks_ = remoteRankToChannelInfo_[0];
485	        interLinks_ = remoteRankToChannelInfo_[1];
486	    }
487	    dataCount_ = param.DataDes.count;
488	    dataType_ = param.DataDes.dataType;
489	    dataTypeSize_ = DATATYPE_SIZE_TABLE[param.DataDes.dataType];
490	    dataSize_ = dataCount_ * dataTypeSize_;
491	
492	    // 获取算法Topo信息
493	    vTopo_ = resCtx.algHierarchyInfo.infos; // 本通信域内的通信平面
494	
495	    // 计算localRankSize
496	    if (resCtx.topoInfo.level0Topo == Level0Shape::MESH_1D_CLOS && !resCtx.topoInfo.level0PcieMix) {
497	        if (resCtx.algHierarchyInfo.infos[0].size() < 2) {
498	            HCCL_ERROR(
499	                "[%s] algHierarchyInfo.infos[0] size[%zu] is less than 2.", __func__,
500	                resCtx.algHierarchyInfo.infos[0].size());
501	            return HcclResult::HCCL_E_PARA;
502	        }
503	        temp0HierarchyInfo_ = {resCtx.algHierarchyInfo.infos[0][0]};
504	        std::vector<u32> closRanks;
505	        u32 meshSize = resCtx.algHierarchyInfo.infos[0][0].size();
506	        for (auto rank : resCtx.algHierarchyInfo.infos[0][1]) {
507	            if (rank % meshSize == resCtx.topoInfo.userRank % meshSize) {
508	                closRanks.push_back(rank);
509	            }
510	        }
511	        temp1HierarchyInfo_ = {closRanks};
512	    } else {
513	        temp0HierarchyInfo_ = resCtx.algHierarchyInfo.infos[0];
514	        temp1HierarchyInfo_ = resCtx.algHierarchyInfo.infos[1];
515	    }
516	
517	    intraLocalRankSize_ = GetRankSize(temp0HierarchyInfo_);
518	    interLocalRankSize_ = GetRankSize(temp1HierarchyInfo_);
519	    rankSize_ = intraLocalRankSize_ * interLocalRankSize_;
520	    HCCL_INFO(
521	        "[Orchestrate] localRankSize: myRank[%d] intraLocalRankSize[%u] interLocalRankSize[%u] rankSize_[%u]", myRank_,
522	        intraLocalRankSize_, interLocalRankSize_, rankSize_);
523	
524	    // 实例化算法模板类
525	    InsAlgTemplate0 tempAlgIntra(param, resCtx.topoInfo.userRank, temp0HierarchyInfo_);
526	    InsAlgTemplate1 tempAlgInter(param, resCtx.topoInfo.userRank, temp1HierarchyInfo_);
527	    InsAlgTemplate2 tempAlgIntra1(param, resCtx.topoInfo.userRank, temp0HierarchyInfo_);
528	    InsAlgTemplate3 tempAlgInter1(param, resCtx.topoInfo.userRank, temp1HierarchyInfo_);
529	    if (param.engine == CommEngine::COMM_ENGINE_AICPU_TS) {
530	        tempAlgInter.SetchannelsPerRank(interLinks_);
531	        tempAlgInter1.SetchannelsPerRank(interLinks_);
532	    }
533	
534	    // 算法展开
535	    HcclResult ret = GenInsQues(param, resCtx, tempAlgIntra, tempAlgInter, tempAlgIntra1, tempAlgInter1);
536	    CHK_PRT_RET(
537	        ret != HCCL_SUCCESS,
538	        HCCL_ERROR(
539	            "[InsAllReduceParallelExecutor][Orchestrate]errNo[0x%016llx] AllReduce executor kernel run failed",
540	            HCCL_ERROR_CODE(ret)),
541	        ret);
542	    return HcclResult::HCCL_SUCCESS;
543	}
