579	template <
580	    typename AlgTopoMatch, typename InsAlgTemplate0, typename InsAlgTemplate1, typename InsAlgTemplate2,
581	    typename InsAlgTemplate3>
582	HcclResult
583	InsAllReduceParallelExecutor<AlgTopoMatch, InsAlgTemplate0, InsAlgTemplate1, InsAlgTemplate2, InsAlgTemplate3>::
584	    PrepareResForTemplate(InsAlgTemplate0& tempAlgIntra, InsAlgTemplate1& tempAlgInter, InsAlgTemplate2& tempAlgIntra1)
585	{
586	    AlgResourceRequest intraTempRequest;
587	    AlgResourceRequest interTempRequest;
588	    AlgResourceRequest intraTempRequest1;
589	    tempAlgIntra.GetRes(intraTempRequest);
590	    tempAlgInter.GetRes(interTempRequest);
591	    tempAlgIntra1.GetRes(intraTempRequest1);
592	    auto intraThreadsNum = intraTempRequest.slaveThreadNum + 1;
593	    auto intraThreadsNum1 = intraTempRequest1.slaveThreadNum + 1;
594	    auto intraThreadsNumFinal = std::max(intraThreadsNum, intraThreadsNum1);
595	    auto intraNotifyOnMainThread = intraTempRequest.notifyNumOnMainThread;
596	    auto interNotifyOnMainThread = interTempRequest.notifyNumOnMainThread;
597	
598	    intraThreads_.clear();
599	    intraThreads_.emplace_back(threads_[1]);
600	    if (intraThreadsNum + 2 >= 3) {
601	        for (u32 i = 3; i < intraThreadsNum + 2; i++) {
602	            intraThreads_.emplace_back(threads_[i]);
603	        }
604	    }
605	
606	    interThreads_.clear();
607	    interThreads_.emplace_back(threads_[intraThreadsNumFinal + 2]);
608	    if (threads_.size() >= intraThreadsNumFinal + 4) {
609	        for (u32 i = intraThreadsNumFinal + 4; i < threads_.size(); i++) {
610	            interThreads_.emplace_back(threads_[i]);
611	        }
612	    }
613	
614	    // 用于两个算法同步
615	    mainThread_ = threads_.at(0);
616	    templateMainThreads_.clear();
617	    templateMainThreads_.emplace_back(intraThreads_.at(0));
618	    templateMainThreads_.emplace_back(interThreads_.at(0));
619	    syncNotifyOnTemplates_ = {intraNotifyOnMainThread, interNotifyOnMainThread};
620	    syncNotifyOnMain_ = {0, 1};
621	
622	    return HcclResult::HCCL_SUCCESS;
623	}
