628	HcclResult
629	InsAllReduceParallelExecutor<AlgTopoMatch, InsAlgTemplate0, InsAlgTemplate1, InsAlgTemplate2, InsAlgTemplate3>::
630	    PrepareResForTemplate23(
631	        InsAlgTemplate0& tempAlgIntra, InsAlgTemplate2& tempAlgIntra1, InsAlgTemplate3& tempAlgInter1)
632	{
633	    AlgResourceRequest intraTempRequest;
634	    AlgResourceRequest interTempRequest1;
635	    AlgResourceRequest intraTempRequest1;
636	    tempAlgIntra.GetRes(intraTempRequest);
637	    tempAlgInter1.GetRes(interTempRequest1);
638	    tempAlgIntra1.GetRes(intraTempRequest1);
639	    auto intraNotifyOnMainThread = intraTempRequest1.notifyNumOnMainThread;
640	    auto interNotifyOnMainThread = interTempRequest1.notifyNumOnMainThread;
641	    auto intraThreadsNum = intraTempRequest.slaveThreadNum + 1;
642	    auto intraThreadsNum1 = intraTempRequest1.slaveThreadNum + 1;
643	    auto intraThreadsNumFinal = std::max(intraThreadsNum, intraThreadsNum1);
644	
645	    intraThreads_.assign(threads_.begin() + 2, threads_.begin() + intraThreadsNum1 + 2);
646	    interThreads_.assign(threads_.begin() + intraThreadsNumFinal + 3, threads_.end());
647	    // 用于两个算法同步
648	    mainThread_ = threads_.at(0);
649	
650	    templateMainThreads_.clear();
651	    templateMainThreads_.emplace_back(intraThreads_.at(0));
652	    templateMainThreads_.emplace_back(interThreads_.at(0));
653	    syncNotifyOnMain_ = {0, 1};
654	    syncNotifyOnTemplates_ = {intraNotifyOnMainThread, interNotifyOnMainThread};
655	
656	    return HcclResult::HCCL_SUCCESS;
657	}
