662	HcclResult
663	InsAllReduceParallelExecutor<AlgTopoMatch, InsAlgTemplate0, InsAlgTemplate1, InsAlgTemplate2, InsAlgTemplate3>::
664	    PrepareResForTemplateResource(
665	        const OpParam& param, const AlgResourceCtxSerializable& resCtx, TemplateResource& intraTempAlgRes,
666	        TemplateResource& interTempAlgRes, bool isRsStage)
667	{
668	    if (param.engine == COMM_ENGINE_CCU) {
669	        if (isRsStage) {
670	            intraTempAlgRes.ccuKernels.insert(
671	                intraTempAlgRes.ccuKernels.end(), resCtx.ccuKernels.begin(),
672	                resCtx.ccuKernels.begin() + resCtx.ccuKernelNum[0]);
673	            interTempAlgRes.ccuKernels.insert(
674	                interTempAlgRes.ccuKernels.end(), resCtx.ccuKernels.begin() + resCtx.ccuKernelNum[0],
675	                resCtx.ccuKernels.begin() + resCtx.ccuKernelNum[0] + resCtx.ccuKernelNum[1]);
676	        } else {
677	            intraTempAlgRes.ccuKernels.insert(
678	                intraTempAlgRes.ccuKernels.end(),
679	                resCtx.ccuKernels.begin() + resCtx.ccuKernelNum[0] + resCtx.ccuKernelNum[1],
680	                resCtx.ccuKernels.begin() + resCtx.ccuKernelNum[0] + resCtx.ccuKernelNum[1] + resCtx.ccuKernelNum[2]);
681	            interTempAlgRes.ccuKernels.insert(
682	                interTempAlgRes.ccuKernels.end(),
683	                resCtx.ccuKernels.begin() + resCtx.ccuKernelNum[0] + resCtx.ccuKernelNum[1] + resCtx.ccuKernelNum[2],
684	                resCtx.ccuKernels.begin() + resCtx.ccuKernelNum[0] + resCtx.ccuKernelNum[1] + resCtx.ccuKernelNum[2]
685	                    + resCtx.ccuKernelNum[3]);
686	        }
687	        interTempAlgRes.dieSplitRatio = resCtx.dieSplitRatio;
688	    } else {
689	        intraTempAlgRes.channels = intraLinks_;
690	        interTempAlgRes.channels = interLinks_;
691	    }
692	    intraTempAlgRes.threads = intraThreads_;
693	    intraTempAlgRes.aivCommInfoPtr = resCtx.aivCommInfoPtr;
694	    for (auto i : intraTempAlgRes.channels) {
695	        HCCL_DEBUG(
696	            "[InsAllReduceParallelExecutor][PrepareResForTemplateResource],intraTempAlgRes.channels, myRank_[%u], "
697	            "channels[%u]= size[%u] ",
698	            myRank_, i.first, i.second.size());
699	    }
700	    interTempAlgRes.threads = interThreads_;
701	    interTempAlgRes.aivCommInfoPtr = resCtx.aivCommInfoPtr;
702	    for (auto i : interTempAlgRes.channels) {
703	        HCCL_DEBUG(
704	            "[InsAllReduceParallelExecutor][PrepareResForTemplateResource],interTempAlgRes.channels, myRank_[%u], "
705	            "channels[%u]= size[%u] ",
706	            myRank_, i.first, i.second.size());
707	    }
708	    HCCL_DEBUG(
709	        "[InsAllReduceParallelExecutor][PrepareResForTemplateResource] AlgTemplate intraThreads_size[%d] "
710	        "interThreads_size[%d]",
711	        intraThreads_.size(), interThreads_.size());
712	
713	    return HcclResult::HCCL_SUCCESS;
714	}
