723	        const u64 outputOffset, const u64 hcclBuffOffset) const
724	{
725	    GenDataParamsAllRank(sliceCount, LocalRankSize, dataParams);
726	
727	    dataParams.buffInfo.inputPtr
728	        = dataParams.buffInfo.inBuffType == BufferType::HCCL_BUFFER ? resCtx.cclMem.addr : param.inputPtr;
729	    dataParams.buffInfo.inputSize
730	        = dataParams.buffInfo.inBuffType == BufferType::HCCL_BUFFER ? resCtx.cclMem.size : param.inputSize;
731	    dataParams.buffInfo.outputPtr
732	        = dataParams.buffInfo.outBuffType == BufferType::HCCL_BUFFER ? resCtx.cclMem.addr : param.outputPtr;
733	    dataParams.buffInfo.outputSize
734	        = dataParams.buffInfo.outBuffType == BufferType::HCCL_BUFFER ? resCtx.cclMem.size : param.outputSize;
735	    dataParams.buffInfo.hcclBuff = resCtx.cclMem;
736	    dataParams.buffInfo.hcclBuffSize = resCtx.cclMem.size;
737	
738	    dataParams.buffInfo.hcclBuffBaseOff = scratchOffsetCount * dataTypeSize_ + hcclBuffOffset;
739	    dataParams.buffInfo.inBuffBaseOff = dataParams.buffInfo.inBuffType == BufferType::HCCL_BUFFER ?
740	                                            scratchOffsetCount * dataTypeSize_ + inputOffset :
741	                                            dataOffset;
742	    dataParams.buffInfo.outBuffBaseOff = dataParams.buffInfo.outBuffType == BufferType::HCCL_BUFFER ?
743	                                             scratchOffsetCount * dataTypeSize_ + outputOffset :
744	                                             dataOffset;
745	    dataParams.repeatNum = 1;
746	    dataParams.inputRepeatStride = 0;
747	    dataParams.outputRepeatStride = 0;
748	
749	    return;
750	}
