800	template <
801	    typename AlgTopoMatch, typename InsAlgTemplate0, typename InsAlgTemplate1, typename InsAlgTemplate2,
802	    typename InsAlgTemplate3>
803	void InsAllReduceParallelExecutor<AlgTopoMatch, InsAlgTemplate0, InsAlgTemplate1, InsAlgTemplate2, InsAlgTemplate3>::
804	    FillDataMap(
805	        const u64 sliceCount, const u32 part1, const u32 part2, std::map<u32, std::pair<u64, u64>>& dataMap,
806	        bool isInter)
807	{
808	    u64 sliceSize = sliceCount * dataTypeSize_;
809	    u64 rankStridePart1 = RoundDown(sliceSize, (part1 * dataTypeSize_)) * dataTypeSize_;
810	    u32 rankId = 0;
811	    u64 curSizePart1 = 0;
812	    u64 rankStridePart2 = 0;
813	    u64 curSizePart2 = 0;
814	
815	    for (u32 i = 0; i < part1; ++i) {
816	        curSizePart1 = (i == (part1 - 1)) ? (sliceSize - rankStridePart1 * i) : rankStridePart1;
817	        rankStridePart2 = RoundDown(curSizePart1, (part2 * dataTypeSize_)) * dataTypeSize_;
818	        for (u32 j = 0; j < part2; ++j) {
819	            curSizePart2 = (j == (part2 - 1)) ? (curSizePart1 - rankStridePart2 * j) : rankStridePart2;
820	
821	            if (isInter) {
822	                rankId = CalcRankIdInter(i, j, part2);
823	            } else {
824	                rankId = CalcRankIdIntra(i, j, part1);
825	            }
826	
827	            dataMap[rankId] = std::make_pair(rankStridePart2, curSizePart2);
828	        }
829	    }
830	}
