833	    typename AlgTopoMatch, typename InsAlgTemplate0, typename InsAlgTemplate1, typename InsAlgTemplate2,
834	    typename InsAlgTemplate3>
835	void InsAllReduceParallelExecutor<AlgTopoMatch, InsAlgTemplate0, InsAlgTemplate1, InsAlgTemplate2, InsAlgTemplate3>::
836	    FillOffsetMaps(
837	        const std::map<u32, std::pair<u64, u64>>& dataMap, const u32 part1, const u32 part2, std::map<u32, u64>& agMap,
838	        bool isInter)
839	{
840	    u64 baseOffAG = 0;
841	    u64 accumAG = 0;
842	    u32 rankId = 0;
843	    u64 result = 0;
844	
845	    for (u32 i = 0; i < part1; ++i) {
846	        for (u32 j = 0; j < part2; ++j) {
847	            if (isInter) {
848	                rankId = CalcRankIdInter(i, j, part2);
849	            } else {
850	                rankId = CalcRankIdIntra(i, j, part1);
851	            }
852	
853	            agMap.insert(std::make_pair(rankId, baseOffAG));
854	
855	            result = (j == (part2 - 1)) ? dataMap.find(rankId)->second.second : dataMap.find(rankId)->second.first;
856	            accumAG += result;
857	        }
858	        baseOffAG += accumAG;
859	        accumAG = 0;
860	    }
861	}
