947	template <
948	    typename AlgTopoMatch, typename InsAlgTemplate0, typename InsAlgTemplate1, typename InsAlgTemplate2,
949	    typename InsAlgTemplate3>
950	HcclResult
951	InsAllReduceParallelExecutor<AlgTopoMatch, InsAlgTemplate0, InsAlgTemplate1, InsAlgTemplate2, InsAlgTemplate3>::
952	    GenInsQues(
953	        const OpParam& param, const AlgResourceCtxSerializable& resCtx, InsAlgTemplate0& tempAlgIntra,
954	        InsAlgTemplate1& tempAlgInter, InsAlgTemplate2& tempAlgIntra1, InsAlgTemplate3& tempAlgInter1)
955	{
956	    HCCL_INFO("[InsAllReduceParallelExecutor] AlgTemplate intra server is [%s]", tempAlgIntra.Describe().c_str());
957	    HCCL_INFO("[InsAllReduceParallelExecutor] AlgTemplate inter server is [%s]", tempAlgInter.Describe().c_str());
958	
959	    multipleDimensionSplitRatio_ = param.opConfig.multipleDimensionSplitRatio;
960	    multipleDimensionSplitRatioSource_ = param.opConfig.multipleDimensionSplitRatioSource;
961	    std::vector<float> dataSplitSize;
962	    GetParallelDataSplit(dataSplitSize);
963	
964	    u32 multipleIntra = tempAlgIntra.CalcScratchMultiple(BufferType::INPUT, BufferType::OUTPUT);
965	    u32 multipleInter = tempAlgInter.CalcScratchMultiple(BufferType::INPUT, BufferType::OUTPUT);
966	    u32 defaultMultiple = 2;
967	    if (multipleIntra > 0 || multipleInter > 0) {
968	        multipleIntra = defaultMultiple;
969	        multipleInter = defaultMultiple;
970	    }
971	
972	    // 按照intraData0+interData1，以及intraData1+interData0两种方式分别计算，取multiple最大需求
973	    float multiple0 = dataSplitSize.at(0) * float(multipleIntra) + dataSplitSize.at(1) * float(multipleInter);
974	    float multiple1 = dataSplitSize.at(1) * float(multipleIntra) + dataSplitSize.at(0) * float(multipleInter);
975	    float multiple = std::max(multiple0, multiple1);
976	
977	    // 数据切分
978	    u64 sliceCountUB = std::min(static_cast<u64>(UB_MAX_DATA_SIZE) / dataTypeSize_, dataCount_);
979	    float sliceCountPercent = std::max(
980	        dataSplitSize.at(0) * float(1.0 / intraLocalRankSize_), dataSplitSize.at(1) * float(1.0 / interLocalRankSize_));
981	    u64 sliceCountUB0 = sliceCountPercent > 0 ? std::floor(double(sliceCountUB) / sliceCountPercent) : sliceCountUB;
982	    u64 sliceCount = sliceCountUB;
983	    if (multiple > 0 && maxTmpMemSize_ > 0) {
984	        u64 scratchCount = maxTmpMemSize_ / dataTypeSize_; // 按照count来切分
985	        sliceCount = std::min(static_cast<u64>(std::floor(double(scratchCount) / multiple)), sliceCountUB0);
986	    }
987	    HCCL_DEBUG(
988	        "[InsAllReduceParallelExecutor][GenInsQues] dataCount_[%lu], myRank_[%d], sliceCountUB[%d], sliceCountUB0[%d], "
989	        "sliceCount[%d]",
990	        dataCount_, myRank_, sliceCountUB, sliceCountUB0, sliceCount);
991	
992	    u64 alignSize = AICPU_ALIGN_SIZE;
993	    u64 sliceCountPart0 = static_cast<u64>(std::floor(double(sliceCount) * dataSplitSize.at(0)));
994	    if (sliceCountPart0 * dataTypeSize_ >= alignSize) {
995	        sliceCountPart0 = sliceCountPart0 * dataTypeSize_ / alignSize * alignSize / dataTypeSize_;
996	    }
997	
998	    if (sliceCount == 0) {
999	        HCCL_WARNING("The divisor cannot be zero.");
1000	        return HcclResult::HCCL_SUCCESS;
1001	    }
1002	    // 计算循环次数
1003	    u32 loopTimes = dataCount_ / sliceCount + ((dataCount_ % sliceCount == 0) ? 0 : 1);
1004	    // 计算Scratch偏移，数据尾块必然小于常规块，不用额外计算尾块时的Scratch偏移
1005	    u64 scratchOffsetCountIntraStage0 = 0;
1006	    u64 scratchOffsetCountInterStage0 = sliceCountPart0 * multipleIntra;
1007	    u64 scratchOffsetCountInterStage1 = 0;
1008	    u64 scratchOffsetCountIntraStage1 = sliceCountPart0 * multipleInter;
1009	    HCCL_DEBUG(
1010	        "[InsAllReduceParallelExecutor][GenInsQues] dataCount_[%lu], myRank_[%d], sliceCountPart0[%d], "
1011	        "multipleIntra[%d]",
1012	        dataCount_, myRank_, sliceCountPart0, multipleIntra);
1013	    HCCL_DEBUG(
1014	        "[InsAllReduceParallelExecutor][GenInsQues] myRank_[%d],scratchOffsetCountInterStage0[%d], "
1015	        "scratchOffsetCountIntraStage1[%d]",
1016	        myRank_, scratchOffsetCountInterStage0, scratchOffsetCountIntraStage1);
1017	    TemplateDataParams tempAlgParamsIntra0;
1018	    TemplateDataParams tempAlgParamsInter0;
1019	    TemplateDataParams tempAlgParamsInter1;
1020	    TemplateDataParams tempAlgParamsIntra1;
1021	    TemplateDataParams tempAlgParamsIntra01;
1022	    TemplateDataParams tempAlgParamsInter01;
1023	    TemplateDataParams tempAlgParamsInter11;
1024	    TemplateDataParams tempAlgParamsIntra11;
1025	
1026	    u64 processedCount = 0;
1027	    u32 loopIndex = 0;
1028	    while (processedCount < dataCount_) {
1029	        u64 remainingCount = dataCount_ - processedCount;
1030	        u32 remainingLoopTimes = (loopIndex < loopTimes) ? (loopTimes - loopIndex) : 1;
1031	        u64 currCount = (remainingCount + remainingLoopTimes - 1) / remainingLoopTimes;
1032	        currCount = std::min(currCount, sliceCount);
1033	        u64 currCountPart0 = static_cast<u64>(std::floor(double(currCount) * dataSplitSize.at(0)));
1034	        u64 currCountPart1 = currCount - currCountPart0;
1035	        if (remainingLoopTimes > 1) {
1036	            u64 alignedCountPart0 = currCountPart0;
1037	            u64 alignedCountPart1 = currCountPart1;
1038	            alignedCountPart0 = alignedCountPart0 * dataTypeSize_ / alignSize * alignSize / dataTypeSize_;
1039	            alignedCountPart1 = alignedCountPart1 * dataTypeSize_ / alignSize * alignSize / dataTypeSize_;
1040	            if (alignedCountPart0 + alignedCountPart1 > 0) {
1041	                currCountPart0 = alignedCountPart0;
1042	                currCountPart1 = alignedCountPart1;
1043	            }
1044	        }
1045	        CHK_PRT_RET(
1046	            currCountPart0 + currCountPart1 == 0,
1047	            HCCL_ERROR("[InsAllReduceParallelExecutor][GenInsQues] currCount is 0"), HcclResult::HCCL_E_INTERNAL);
1048	        u64 dataOffset0 = processedCount * dataTypeSize_;
1049	        u64 dataOffset1 = dataOffset0 + currCountPart0 * dataTypeSize_;
1050	        // 计算算法模板所需资源
1051	        TemplateResource intraTempAlgRes;
1052	        TemplateResource interTempAlgRes;
1053	        CHK_RET(PrepareResForTemplate(tempAlgIntra, tempAlgInter, tempAlgIntra1));
1054	        CHK_RET(PrepareResForTemplateResource(param, resCtx, intraTempAlgRes, interTempAlgRes, true));
1055	        // server 间地址偏移
1056	        for (int i = 0; i < temp0HierarchyInfo_[0].size(); i++) {
1057	            tempVirtRankMapInter_.insert(std::make_pair(temp0HierarchyInfo_[0][i], i));
1058	        }
1059	        // server 内地址偏移
1060	        for (int i = 0; i < temp1HierarchyInfo_[0].size(); i++) {
1061	            tempVirtRankMapIntra_.insert(std::make_pair(temp1HierarchyInfo_[0][i], i));
1062	        }
1063	        CalcIntraDataAllRank(currCountPart0, intraLocalRankSize_, interLocalRankSize_, meshPartDataMap_);
1064	        CalcInterDataAllRank(currCountPart1, interLocalRankSize_, intraLocalRankSize_, nhrPartDataMap_);
1065	        // 第一步开始前同步
1066	        CHK_RET(PreSyncInterThreads(mainThread_, templateMainThreads_, syncNotifyOnTemplates_));
1067	        CHK_RET(RunTemplateIntra0(
1068	            param, resCtx, dataOffset0, currCountPart0, scratchOffsetCountIntraStage0, tempAlgParamsIntra0,
1069	            intraTempAlgRes, tempAlgIntra));
1070	        CHK_RET(RunTemplateInter1(
1071	            param, resCtx, dataOffset1, currCountPart1, scratchOffsetCountInterStage0, tempAlgParamsInter1,
1072	            interTempAlgRes, tempAlgInter));
1073	        // 第一步做完后回到主流做尾同步
1074	        CHK_RET(PostSyncInterThreads(mainThread_, templateMainThreads_, syncNotifyOnMain_));
1075	
1076	#ifndef AICPU_COMPILE
1077	        if (loopTimes == 1 && param.engine == CommEngine::COMM_ENGINE_CCU) {
1078	            ccuKernelLaunchNumIntra0_ = intraTempAlgRes.submitInfos.size();
1079	            ccuKernelLaunchNumInter1_ = interTempAlgRes.submitInfos.size();
1080	        }
1081	#endif
1082	
1083	        // 第二步开始前同步
1084	        CHK_RET(PreSyncInterThreads(mainThread_, templateMainThreads_, syncNotifyOnTemplates_));
1085	        CHK_RET(RunTemplateInter0(
1086	            param, resCtx, dataOffset0, currCountPart0, scratchOffsetCountInterStage1, tempAlgParamsInter0,
1087	            interTempAlgRes, tempAlgInter));
1088	        CHK_RET(RunTemplateIntra1(
1089	            param, resCtx, dataOffset1, currCountPart1, scratchOffsetCountIntraStage1, tempAlgParamsIntra1,
1090	            intraTempAlgRes, tempAlgIntra));
1091	        // 尾同步
1092	        CHK_RET(PostSyncInterThreads(mainThread_, templateMainThreads_, syncNotifyOnMain_));
1093	
1094	#ifndef AICPU_COMPILE
1095	        if (loopTimes == 1 && param.engine == CommEngine::COMM_ENGINE_CCU) {
1096	            ccuKernelLaunchNumIntra1_ = intraTempAlgRes.submitInfos.size() - ccuKernelLaunchNumIntra0_;
1097	            ccuKernelLaunchNumInter0_ = interTempAlgRes.submitInfos.size() - ccuKernelLaunchNumInter1_;
1098	        }
1099	#endif
1100	
1101	        // 计算算法模板所需资源 InsAlgTemplate2 &tempAlgIntra1, InsAlgTemplate3 &tempAlgInter1
1102	        TemplateResource intraTempAlgRes1;
1103	        TemplateResource interTempAlgRes1;
1104	        CHK_RET(PrepareResForTemplate23(tempAlgIntra, tempAlgIntra1, tempAlgInter1));
1105	        CHK_RET(PrepareResForTemplateResource(param, resCtx, intraTempAlgRes1, interTempAlgRes1, false));
1106	
1107	        // 第三步开始前同步
1108	        CHK_RET(PreSyncInterThreads(mainThread_, templateMainThreads_, syncNotifyOnTemplates_));
1109	        CHK_RET(RunTemplateInter01(
1110	            param, resCtx, dataOffset0, currCountPart0, scratchOffsetCountInterStage1, tempAlgParamsInter01,
1111	            interTempAlgRes1, tempAlgInter1));
1112	        CHK_RET(RunTemplateIntra11(
1113	            param, resCtx, dataOffset1, currCountPart1, scratchOffsetCountIntraStage1, tempAlgParamsIntra11,
1114	            intraTempAlgRes1, tempAlgIntra1));
1115	        // 尾同步
1116	        CHK_RET(PostSyncInterThreads(mainThread_, templateMainThreads_, syncNotifyOnMain_));
1117	
1118	#ifndef AICPU_COMPILE
1119	        if (loopTimes == 1 && param.engine == CommEngine::COMM_ENGINE_CCU) {
1120	            ccuKernelLaunchNumIntra11_ = intraTempAlgRes1.submitInfos.size();
1121	            ccuKernelLaunchNumInter00_ = interTempAlgRes1.submitInfos.size();
1122	        }
1123	#endif
1124	
1125	        // 第四步开始前同步
1126	        CHK_RET(PreSyncInterThreads(mainThread_, templateMainThreads_, syncNotifyOnTemplates_));
1127	        CHK_RET(RunTemplateIntra01(
1128	            param, resCtx, dataOffset0, currCountPart0, scratchOffsetCountIntraStage0, tempAlgParamsIntra01,
1129	            intraTempAlgRes1, tempAlgIntra1));
1130	        CHK_RET(RunTemplateInter11(
1131	            param, resCtx, dataOffset1, currCountPart1, scratchOffsetCountInterStage0, tempAlgParamsInter11,
1132	            interTempAlgRes1, tempAlgInter1));
1133	        // 第四步做完后回到主流做尾同步
1134	        CHK_RET(PostSyncInterThreads(mainThread_, templateMainThreads_, syncNotifyOnMain_));
1135	
1136	#ifndef AICPU_COMPILE
1137	        if (loopTimes == 1 && param.engine == CommEngine::COMM_ENGINE_CCU && param.opMode != OpMode::OFFLOAD) {
1138	            ccuKernelLaunchNumIntra00_ = intraTempAlgRes1.submitInfos.size() - ccuKernelLaunchNumIntra11_;
1139	            ccuKernelLaunchNumInter11_ = interTempAlgRes1.submitInfos.size() - ccuKernelLaunchNumInter00_;
1140	            CHK_RET(FastLaunchSaveCtx(
1141	                param, intraTempAlgRes, interTempAlgRes, intraTempAlgRes1, interTempAlgRes1,
1142	                resCtx.notifyNumOnMainThread));
1143	        }
1144	#endif
1145	
1146	        processedCount += currCountPart0 + currCountPart1;
1147	        loopIndex++;
1148	    }
1149	
1150	    HCCL_INFO("[InsAllReduceParallelExecutor][GenInsQues] End.myRank[%d]", myRank_);
1151	    return HcclResult::HCCL_SUCCESS;
1152	}
