145	    AlgResourceRequest resReqReduceScatterMesh1dDpu;
146	    AlgResourceRequest resReqAllGatherNhrDPU;
147	    AlgResourceRequest resReqAllGatherMesh1D;
148	    CHK_RET(reduceScatterMesh1DTempAlg->CalcRes(comm, param, topoInfo, resReqReduceScatterMesh1D));
149	    CHK_RET(reduceScatterMesh1dDpuTempAlg->CalcRes(comm, param, topoInfo, resReqReduceScatterMesh1dDpu));
150	    CHK_RET(allGatherNhrDPUTempAlg->CalcRes(comm, param, topoInfo, resReqAllGatherNhrDPU));
151	    CHK_RET(allGatherMesh1DTempAlg->CalcRes(comm, param, topoInfo, resReqAllGatherMesh1D));
152	
153	    // step1、2、3、4为串行，因此slaveThread和对应notify可以复用
154	    resourceRequest.slaveThreadNum
155	        = std::max(resReqReduceScatterMesh1D.slaveThreadNum, resReqReduceScatterMesh1dDpu.slaveThreadNum);
156	    resourceRequest.notifyNumPerThread.clear();
157	    resourceRequest.notifyNumPerThread.resize(resourceRequest.slaveThreadNum);
158	    for (u32 i = 0; i < resourceRequest.slaveThreadNum; ++i) {
159	        if (i < resReqReduceScatterMesh1D.notifyNumPerThread.size()) {
160	            resourceRequest.notifyNumPerThread[i]
161	                = std::max(resourceRequest.notifyNumPerThread[i], resReqReduceScatterMesh1D.notifyNumPerThread[i]);
162	        }
163	        if (i < resReqReduceScatterMesh1dDpu.notifyNumPerThread.size()) {
164	            resourceRequest.notifyNumPerThread[i]
165	                = std::max(resourceRequest.notifyNumPerThread[i], resReqReduceScatterMesh1dDpu.notifyNumPerThread[i]);
166	        }
167	    }
168	    resourceRequest.notifyNumOnMainThread
169	        = std::max(resReqReduceScatterMesh1D.notifyNumOnMainThread, resReqReduceScatterMesh1dDpu.notifyNumOnMainThread);
170	
171	    resourceRequest.channels = {resReqReduceScatterMesh1D.channels[0], resReqReduceScatterMesh1dDpu.channels[0]};
172	    return HCCL_SUCCESS;
173	}
174	
175	template <
176	    typename AlgTopoMatch, typename InsAlgTemplate0, typename InsAlgTemplate1, typename InsAlgTemplate2,
177	    typename InsAlgTemplate3>
178	HcclResult
179	InsV2AllReduceSequenceExecutor<AlgTopoMatch, InsAlgTemplate0, InsAlgTemplate1, InsAlgTemplate2, InsAlgTemplate3>::
180	    Orchestrate(const OpParam& param, const AlgResourceCtxSerializable& resCtx)
181	{
182	    HCCL_INFO("[InsV2AllReduceSequenceExecutor][Orchestrate] Orchestrate Start");
183	    // 参数填充
184	    myRank_ = resCtx.topoInfo.userRank;
185	    rankSize_ = resCtx.topoInfo.userRankSize;
186	
187	    dataTypeSize_ = HCCL_SIZE_TABLE[param.DataDes.dataType];
188	    dataSize_ = dataCount_ * dataTypeSize_;
189	    dataCount_ = param.DataDes.count;
190	    dataType_ = param.DataDes.dataType;
191	    reduceOp_ = param.reduceType;
192	    algHierarchyInfo_ = resCtx.algHierarchyInfo;
193	    threads_ = resCtx.threads;
194	
195	    rankIdxLevel0_ = myRank_ % algHierarchyInfo_.infos[0][0].size();
196	    rankIdxLevel1_ = myRank_ / algHierarchyInfo_.infos[0][0].size();
197	
198	    rankSizeLevel0_ = algHierarchyInfo_.infos[0][0].size();
199	    rankSizeLevel1_ = algHierarchyInfo_.infos[1][0].size();
200	    CHK_RET(RestoreChannelMap(resCtx, remoteRankToChannelInfo_));
201	
202	    // 算法展开
203	    HcclResult ret = OrchestrateLoop(param, resCtx);
204	    CHK_PRT_RET(
205	        ret != HCCL_SUCCESS,
206	        HCCL_ERROR(
207	            "[InsV2AllReduceSequenceExecutor][Orchestrate]errNo[0x%016llx] AllReduce executor kernel run failed",
208	            HCCL_ERROR_CODE(ret)),
209	        ret);
210	    return HCCL_SUCCESS;
211	}
212	
213	template <
214	    typename AlgTopoMatch, typename InsAlgTemplate0, typename InsAlgTemplate1, typename InsAlgTemplate2,
215	    typename InsAlgTemplate3>
216	HcclResult
217	InsV2AllReduceSequenceExecutor<AlgTopoMatch, InsAlgTemplate0, InsAlgTemplate1, InsAlgTemplate2, InsAlgTemplate3>::
218	    OrchestrateLoop(const OpParam& param, const AlgResourceCtxSerializable& resCtx)
219	{
220	    HCCL_INFO("[InsV2AllReduceSequenceExecutor][OrchestrateLoop] Start");
221	    // 将ccl-buffer分成ccl-in和ccl-out 2部分区分使用
222	    void* cclInAddr = resCtx.cclMem.addr;
223	    HcclMem cclInMem = {resCtx.cclMem.type, cclInAddr, resCtx.cclMem.size / 2};
224	    void* cclOutAddr = static_cast<void*>(static_cast<s8*>(resCtx.cclMem.addr) + resCtx.cclMem.size / 2);
225	    HcclMem cclOutMem = {resCtx.cclMem.type, cclOutAddr, resCtx.cclMem.size / 2};
226	
227	    // 声明框内ReduceScatterMesh1D的templateargs
228	    TemplateDataParams tempAlgParamsStepOne;
229	    tempAlgParamsStepOne.buffInfo.inputPtr = param.inputPtr;
230	    tempAlgParamsStepOne.buffInfo.outputPtr = cclOutMem.addr;
231	    tempAlgParamsStepOne.buffInfo.hcclBuff = cclInMem;
232	
233	    // 构建框内ReduceScatterMesh1D的template
234	    std::shared_ptr<InsAlgTemplate0> algTemplateStepOne
235	        = std::make_shared<InsAlgTemplate0>(param, myRank_, algHierarchyInfo_.infos[0]);
236	
237	    // 声明框间ReduceScatterMesh1dDpu的templateargs
238	    TemplateDataParams tempAlgParamsStepTwo;
239	    tempAlgParamsStepTwo.buffInfo.inputPtr = cclOutMem.addr;
240	    tempAlgParamsStepTwo.buffInfo.outputPtr = cclOutMem.addr;
241	    tempAlgParamsStepTwo.buffInfo.hcclBuff = cclInMem;
242	
243	    // 构建框间ReduceScatterMesh1dDpu的template
244	    std::shared_ptr<InsAlgTemplate1> algTemplateStepTwo
245	        = std::make_shared<InsAlgTemplate1>(param, myRank_, algHierarchyInfo_.infos[1]);
246	
247	    // 声明框间AllGatherNhr的templateargs，ccl-out搬运到ccl-out
248	    TemplateDataParams tempAlgParamsStepThree;
249	    tempAlgParamsStepThree.buffInfo.inputPtr = cclOutMem.addr;
250	    tempAlgParamsStepThree.buffInfo.outputPtr = cclOutMem.addr;
251	    tempAlgParamsStepThree.buffInfo.hcclBuff = cclInMem;
252	
253	    // 构建框间AllGatherNhrDPU的template
254	    std::shared_ptr<InsAlgTemplate2> algTemplateStepThree
255	        = std::make_shared<InsAlgTemplate2>(param, myRank_, algHierarchyInfo_.infos[1]);
256	
257	    // 声明框内AllGatherMesh1D的templateargs，ccl-out搬运到user-out
258	    TemplateDataParams tempAlgParamsStepFour;
259	    tempAlgParamsStepFour.buffInfo.inputPtr = cclOutMem.addr;
260	    tempAlgParamsStepFour.buffInfo.outputPtr = param.outputPtr;
261	    tempAlgParamsStepFour.buffInfo.hcclBuff = cclInMem;
262	
263	    // 构建框内AllGatherMesh1D的template
264	    std::shared_ptr<InsAlgTemplate3> algTemplateStepFour
265	        = std::make_shared<InsAlgTemplate3>(param, myRank_, algHierarchyInfo_.infos[0]);
266	
267	    // 构造框内ReduceScatterMesh1D的template资源
268	    TemplateResource templateResourceReduceScatterMesh1D;
269	    templateResourceReduceScatterMesh1D.channels = remoteRankToChannelInfo_[0];
270	    templateResourceReduceScatterMesh1D.threads = resCtx.threads;
271	    templateResourceReduceScatterMesh1D.npu2DpuShmemPtr = resCtx.npu2DpuShmemPtr;
272	    templateResourceReduceScatterMesh1D.dpu2NpuShmemPtr = resCtx.dpu2NpuShmemPtr;
273	    // 构造框间ReduceScatterMesh1dDpu的template资源
274	    TemplateResource templateResourceReduceScatterMesh1dDpu;
275	    templateResourceReduceScatterMesh1dDpu.channels = remoteRankToChannelInfo_[1];
276	    templateResourceReduceScatterMesh1dDpu.threads = resCtx.threads;
277	    templateResourceReduceScatterMesh1dDpu.npu2DpuShmemPtr = resCtx.npu2DpuShmemPtr;
278	    templateResourceReduceScatterMesh1dDpu.dpu2NpuShmemPtr = resCtx.dpu2NpuShmemPtr;
279	    // 构造框间AllGatherNhrDPU的template资源
280	    TemplateResource templateResourceAllGatherNhrDPU;
281	    templateResourceAllGatherNhrDPU.channels = remoteRankToChannelInfo_[1];
282	    templateResourceAllGatherNhrDPU.threads = resCtx.threads;
283	    templateResourceAllGatherNhrDPU.npu2DpuShmemPtr = resCtx.npu2DpuShmemPtr;
284	    templateResourceAllGatherNhrDPU.dpu2NpuShmemPtr = resCtx.dpu2NpuShmemPtr;
285	    // 构造框内AllGatherMesh1D的template资源
286	    TemplateResource templateResourceAllGatherMesh1D;
287	    templateResourceAllGatherMesh1D.channels = remoteRankToChannelInfo_[0];
288	    templateResourceAllGatherMesh1D.threads = resCtx.threads;
289	    templateResourceAllGatherMesh1D.npu2DpuShmemPtr = resCtx.npu2DpuShmemPtr;
290	    templateResourceAllGatherMesh1D.dpu2NpuShmemPtr = resCtx.dpu2NpuShmemPtr;
291	
292	    // 中转内存单次最多能够接受的output count，注意是count不是size
293	    u64 maxCountPerLoop = tempAlgParamsStepOne.buffInfo.hcclBuff.size / 2 / HCCL_MIN_SLICE_ALIGN * HCCL_MIN_SLICE_ALIGN
294	                          / dataTypeSize_; // 这边看前面有/10*10，不知道要不要加上
295	    // 计算loopTimes
296	    u64 loopTimes = dataCount_ / maxCountPerLoop + static_cast<u64>(dataCount_ % maxCountPerLoop != 0);
297	    u64 processedDataCount = 0;
298	    for (u64 loop = 0; loop < loopTimes; loop++) {
299	        u64 currDataCount = (loop == loopTimes - 1) ? dataCount_ - processedDataCount :
300	                                                      maxCountPerLoop; // 判断是最后一轮，就处理尾块长度
301	
302	        // ----------- 框内ReduceScatter数据搬运 -----------
303	        // 框内的数据偏移和搬运计算
304	        tempAlgParamsStepOne.count = currDataCount;
305	        tempAlgParamsStepOne.buffInfo.inBuffBaseOff = processedDataCount * dataTypeSize_;
306	        tempAlgParamsStepOne.buffInfo.outBuffBaseOff = 0;  // CCL-OUT
307	        tempAlgParamsStepOne.buffInfo.hcclBuffBaseOff = 0; // CCL-IN
308	        CHK_RET(
309	            SplitData(currDataCount, rankSizeLevel0_, tempAlgParamsStepOne)); // 计算每个卡对应位置的offset,count,size
310	        CHK_PRT_RET(
311	            tempAlgParamsStepOne.allRankSliceSize.size() != rankSizeLevel0_,
312	            HCCL_ERROR(
313	                "[InsV2AllReduceSequenceExecutor][tempAlgParamsStepOne] slice num[%u] is not equal to rank size[%u].",
314	                tempAlgParamsStepOne.allRankSliceSize.size(), rankSizeLevel0_),
315	            HcclResult::HCCL_E_INTERNAL);
316	        tempAlgParamsStepOne.sliceSize = 0; // 没用到，template里面用SplitData算了
317	        tempAlgParamsStepOne.tailSize = 0;  // 没用到
318	        // 这里的stride当成传统意义上的stride间隔
319	        tempAlgParamsStepOne.inputSliceStride = 0;  // 没用到
320	        tempAlgParamsStepOne.outputSliceStride = 0; // 没用到
321	
322	        HCCL_INFO(
323	            "[InsV2AllReduceSequenceExecutor] loop [%u] tempAlgParamsStepOne.inputSliceStride [%u],"
324	            "tempAlgParamsStepOne.outputSliceStride [%u] tempAlgParamsStepOne.sliceSize [%u]",
325	            loop, tempAlgParamsStepOne.inputSliceStride, tempAlgParamsStepOne.outputSliceStride,
326	            tempAlgParamsStepOne.sliceSize);
327	        HCCL_INFO(
328	            "[InsV2AllReduceSequenceExecutor] loop [%u] tempAlgParamsStepOne.buffInfo.inBuffBaseOff [%u],"
329	            "tempAlgParamsStepOne.buffInfo.outBuffBaseOff [%u]",
330	            loop, tempAlgParamsStepOne.buffInfo.inBuffBaseOff, tempAlgParamsStepOne.buffInfo.outBuffBaseOff);
331	        // 不需要重复
332	        tempAlgParamsStepOne.repeatNum = 1;
333	        tempAlgParamsStepOne.inputRepeatStride = 0;
334	        tempAlgParamsStepOne.outputRepeatStride = 0;
335	        // 因为只考虑执行0级算法，所以传进template里面的channels就是channels_的第一个vector
336	        CHK_RET(algTemplateStepOne->KernelRun(param, tempAlgParamsStepOne, templateResourceReduceScatterMesh1D));
337	
338	        // ----------- 框间ReduceScatterMesh1dDpu数据搬运 -----------
339	        // 框间的数据偏移和搬运量计算
340	        tempAlgParamsStepTwo.count = tempAlgParamsStepOne.allRankProcessedDataCount.at(rankIdxLevel0_);
341	        if (tempAlgParamsStepTwo.count != 0) { // 如果卡里没有数据，不参与框间，让该框有数据的其他卡参与跨框
342	            tempAlgParamsStepTwo.buffInfo.inBuffBaseOff = 0;   // ccl-out偏移量，每次更新，所以是0
343	            tempAlgParamsStepTwo.buffInfo.outBuffBaseOff = 0;  // ccl-out偏移量，每次更新，所以是0
344	            tempAlgParamsStepTwo.buffInfo.hcclBuffBaseOff = 0; // ccl-in
345	            tempAlgParamsStepTwo.sliceSize = 0;
346	            tempAlgParamsStepTwo.tailSize = 0;
347	            CHK_RET(SplitData(tempAlgParamsStepTwo.count, rankSizeLevel1_, tempAlgParamsStepTwo));
348	            CHK_PRT_RET(
349	                tempAlgParamsStepTwo.allRankSliceSize.size() != rankSizeLevel1_,
350	                HCCL_ERROR(
351	                    "[InsV2AllReduceSequenceExecutor][tempAlgParamsStepTwo] slice num[%u] is not "
352	                    "equal to rank size[%u].",
353	                    tempAlgParamsStepTwo.allRankSliceSize.size(), rankSizeLevel1_),
354	                HcclResult::HCCL_E_INTERNAL);
355	            // 这里的stride当成传统意义上的stride 间隔
356	            tempAlgParamsStepTwo.inputSliceStride = 0;  // 没用到
357	            tempAlgParamsStepTwo.outputSliceStride = 0; // 没用到
358	            //
359	            HCCL_INFO(
360	                "[InsV2AllReduceSequenceExecutor] loop [%u] tempAlgParamsStepTwo.inputSliceStride [%u],"
361	                "tempAlgParamsStepTwo.outputSliceStride [%u] "
362	                "tempAlgParamsStepTwo.sliceSize [%u]",
363	                loop, tempAlgParamsStepTwo.inputSliceStride, tempAlgParamsStepTwo.outputSliceStride,
364	                tempAlgParamsStepTwo.sliceSize);
365	            HCCL_INFO(
366	                "[InsV2AllReduceSequenceExecutor] loop [%u] "
367	                "tempAlgParamsStepTwo.buffInfo.inBuffBaseOff [%u],"
368	                "tempAlgParamsStepTwo.buffInfo.outBuffBaseOff [%u]",
369	                loop, tempAlgParamsStepTwo.buffInfo.inBuffBaseOff, tempAlgParamsStepTwo.buffInfo.outBuffBaseOff);
370	
371	            tempAlgParamsStepTwo.repeatNum = 1;
372	            tempAlgParamsStepTwo.inputRepeatStride = 0;
373	            tempAlgParamsStepTwo.outputRepeatStride = 0;
374	
375	            CHK_RET(algTemplateStepTwo->KernelRun(param, tempAlgParamsStepTwo, templateResourceReduceScatterMesh1dDpu));
376	        }
377	
378	        // ----------- 框间AllGatherNhr数据搬运 -----------
379	        // 框间的数据偏移和搬运量计算
380	        tempAlgParamsStepThree.count = tempAlgParamsStepOne.allRankProcessedDataCount.at(rankIdxLevel0_);
381	        if (tempAlgParamsStepTwo.count != 0) {
382	            tempAlgParamsStepThree.buffInfo.inBuffBaseOff = 0;   // ccl-out偏移量，每次更新，所以是0
383	            tempAlgParamsStepThree.buffInfo.outBuffBaseOff = 0;  // ccl-out偏移量，每次更新，所以是0
384	            tempAlgParamsStepThree.buffInfo.hcclBuffBaseOff = 0; // ccl-in
385	            tempAlgParamsStepThree.allRankDispls = tempAlgParamsStepTwo.allRankDispls;
386	            tempAlgParamsStepThree.allRankSliceSize = tempAlgParamsStepTwo.allRankSliceSize;
387	            tempAlgParamsStepThree.allRankProcessedDataCount = tempAlgParamsStepTwo.allRankProcessedDataCount;
388	
389	            tempAlgParamsStepThree.sliceSize = 0;
390	            tempAlgParamsStepThree.tailSize = 0;
391	            // 这里的stride当成传统意义上的stride 间隔
392	            tempAlgParamsStepThree.inputSliceStride = 0;
393	            tempAlgParamsStepThree.outputSliceStride = 0;
394	
395	            HCCL_INFO(
396	                "[InsV2AllReduceSequenceExecutor] loop [%u] tempAlgParamsStepThree.inputSliceStride [%u],"
397	                "tempAlgParamsStepThree.outputSliceStride [%u] tempAlgParamsStepThree.sliceSize [%u]",
398	                loop, tempAlgParamsStepThree.inputSliceStride, tempAlgParamsStepThree.outputSliceStride,
399	                tempAlgParamsStepThree.sliceSize);
400	            HCCL_INFO(
401	                "[InsV2AllReduceSequenceExecutor] loop [%u] tempAlgParamsStepThree.buffInfo.inBuffBaseOff [%u],"
402	                "tempAlgParamsStepThree.buffInfo.outBuffBaseOff [%u]",
403	                loop, tempAlgParamsStepThree.buffInfo.inBuffBaseOff, tempAlgParamsStepThree.buffInfo.outBuffBaseOff);
404	
405	            tempAlgParamsStepThree.repeatNum = 1;
406	            tempAlgParamsStepThree.inputRepeatStride = 0;
407	            tempAlgParamsStepThree.outputRepeatStride = 0;
408	
409	            CHK_RET(algTemplateStepThree->KernelRun(param, tempAlgParamsStepThree, templateResourceAllGatherNhrDPU));
410	        }
411	
412	        // ----------- 框内AllGatherMesh数据搬运 -----------
413	        // 框内的数据偏移和搬运计算
414	        tempAlgParamsStepFour.count = currDataCount;
415	        tempAlgParamsStepFour.buffInfo.inBuffBaseOff = 0;                                   // CCL-OUT
416	        tempAlgParamsStepFour.buffInfo.outBuffBaseOff = processedDataCount * dataTypeSize_; // USR-OUT
417	        tempAlgParamsStepFour.buffInfo.hcclBuffBaseOff = 0;                                 // CCL-IN
418	        tempAlgParamsStepFour.allRankDispls = tempAlgParamsStepOne.allRankDispls;
419	        tempAlgParamsStepFour.allRankSliceSize = tempAlgParamsStepOne.allRankSliceSize;
420	        tempAlgParamsStepFour.allRankProcessedDataCount = tempAlgParamsStepOne.allRankProcessedDataCount;
421	
422	        tempAlgParamsStepFour.sliceSize = 0;
423	        tempAlgParamsStepFour.tailSize = 0;
424	        // 这里的stride当成传统意义上的stride间隔
425	        tempAlgParamsStepFour.inputSliceStride = 0;
426	        tempAlgParamsStepFour.outputSliceStride = 0;
427	
428	        HCCL_INFO(
429	            "[InsV2AllReduceSequenceExecutor] loop [%u] tempAlgParamsStepFour.inputSliceStride [%u],"
430	            "tempAlgParamsStepFour.outputSliceStride [%u] tempAlgParamsStepFour.sliceSize [%u]",
431	            loop, tempAlgParamsStepFour.inputSliceStride, tempAlgParamsStepFour.outputSliceStride,
432	            tempAlgParamsStepFour.sliceSize);
433	        HCCL_INFO(
434	            "[InsV2AllReduceSequenceExecutor] loop [%u] tempAlgParamsStepFour.buffInfo.inBuffBaseOff [%u],"
435	            "tempAlgParamsStepFour.buffInfo.outBuffBaseOff [%u]",
436	            loop, tempAlgParamsStepFour.buffInfo.inBuffBaseOff, tempAlgParamsStepFour.buffInfo.outBuffBaseOff);
437	
438	        tempAlgParamsStepFour.repeatNum = 1;
439	        tempAlgParamsStepFour.inputRepeatStride = 0;
440	        tempAlgParamsStepFour.outputRepeatStride = 0;
441	
442	        CHK_RET(algTemplateStepFour->KernelRun(param, tempAlgParamsStepFour, templateResourceAllGatherMesh1D));
443	
444	        processedDataCount += currDataCount;
445	    }
446	    HCCL_INFO("[InsV2AllReduceSequenceExecutor][OrchestrateLoop] End.");
447	    return HCCL_SUCCESS;
448	}
449	
450	template <
451	    typename AlgTopoMatch, typename InsAlgTemplate0, typename InsAlgTemplate1, typename InsAlgTemplate2,
452	    typename InsAlgTemplate3>
453	u64 InsV2AllReduceSequenceExecutor<AlgTopoMatch, InsAlgTemplate0, InsAlgTemplate1, InsAlgTemplate2, InsAlgTemplate3>::
454	    RoundUp(const u64 dividend, const u64 divisor)
455	{
456	    if (divisor == 0) {
457	        HCCL_WARNING("[InsV2AllReduceSequenceExecutor][RoundUp] divisor is 0.");
458	        return dividend;
459	    }
460	    return (dividend + divisor - 1) / divisor;
461	}
462	
463	template <
464	    typename AlgTopoMatch, typename InsAlgTemplate0, typename InsAlgTemplate1, typename InsAlgTemplate2,
465	    typename InsAlgTemplate3>
466	HcclResult
467	InsV2AllReduceSequenceExecutor<AlgTopoMatch, InsAlgTemplate0, InsAlgTemplate1, InsAlgTemplate2, InsAlgTemplate3>::
468	    SplitData(const u64& dataCount, const uint64_t& rankSize, TemplateDataParams& tempAlgParams)
469	{
470	    u32 sliceNum = rankSize;
471	    tempAlgParams.allRankSliceSize.clear();
472	    tempAlgParams.allRankProcessedDataCount.clear();
473	    tempAlgParams.allRankDispls.clear();
474	    tempAlgParams.allRankSliceSize.reserve(sliceNum);
475	    tempAlgParams.allRankDispls.reserve(sliceNum);
476	    tempAlgParams.allRankProcessedDataCount.reserve(sliceNum);
477	
478	    u64 offsetCount = 0;
479	    u64 offsetSize = 0;
480	    u64 sliceCount = RoundUp(dataCount, sliceNum);
481	    u64 sliceSize = sliceCount * dataTypeSize_;
482	
483	    for (u32 sliceIdx = 0; sliceIdx < sliceNum; ++sliceIdx) {
484	        if (dataCount - offsetCount >= sliceCount) {
485	            tempAlgParams.allRankSliceSize.emplace_back(sliceSize);
486	            tempAlgParams.allRankProcessedDataCount.emplace_back(sliceCount);
487	            tempAlgParams.allRankDispls.emplace_back(offsetSize);
488	            offsetCount += sliceCount;
489	            offsetSize = offsetCount * dataTypeSize_;
490	        } else {
491	            u64 curSliceCount = dataCount - offsetCount;
492	            u64 curSliceSize = curSliceCount * dataTypeSize_;
493	            tempAlgParams.allRankSliceSize.emplace_back(curSliceSize);
494	            tempAlgParams.allRankProcessedDataCount.emplace_back(curSliceCount);
495	            tempAlgParams.allRankDispls.emplace_back(offsetSize);
496	            offsetCount = dataCount;
497	            offsetSize = offsetCount * dataTypeSize_;
498	        }
499	    }
500	
501	    for (u32 i = 0; i < tempAlgParams.allRankSliceSize.size(); ++i) {
502	        HCCL_DEBUG(
503	            "[InsV2AllReduceSequenceExecutor] SliceInfo: offset[%u] size[%u] count[%u]",
504	            tempAlgParams.allRankDispls.at(i), tempAlgParams.allRankSliceSize.at(i),
505	            tempAlgParams.allRankProcessedDataCount.at(i));
506	    }
507	
508	    return HcclResult::HCCL_SUCCESS;
509	}
