560	HcclResult FallbackOp(
561	    HcclComm comm, OpParam& param, std::unique_ptr<TopoInfoWithNetLayerDetails>& topoInfo, std::string& algName,
562	    const ResPackGraphMode& resPack)
563	{
564	    void* fallbackCtx = nullptr;
565	    uint64_t fallbackCtxSize = ALG_MAX_LENGTH;
566	    CHK_RET(HcclEngineCtxCreate(comm, param.fallbackTag, CommEngine::COMM_ENGINE_CCU, fallbackCtxSize, &fallbackCtx));
567	    char* newAlgName = static_cast<char*>(fallbackCtx);
568	    CHK_RET(ReSelector(comm, param, topoInfo, algName));
569	    auto copyRet = sprintf_s(newAlgName, fallbackCtxSize, "%s", algName.c_str());
570	    if (copyRet <= 0) {
571	        HCCL_ERROR("[%s] failed to fill newAlgName", __func__);
572	        return HCCL_E_INTERNAL;
573	    }
574	    CHK_RET(HcclExecOp(comm, param, topoInfo, algName, resPack));
575	    return HCCL_SUCCESS;
576	}
577	
578	HcclResult
579	ReSelector(HcclComm comm, OpParam& param, std::unique_ptr<TopoInfoWithNetLayerDetails>& topoInfo, std::string& algName)
580	{
581	    (void)comm;
582	    HCCL_INFO("Start to execute ReSelector.");
583	    // 回退AICPU
584	    param.opExecuteConfig = OpExecuteConfig::AICPU_TS;
585	    // 拓扑已有，无需再计算
586	
587	    // 算法选择，选择完后顺便param.algTag设置了，资源的保存是以算子+算法为单位
588	    if (IsNewSelectorEnabled() && SelectorEngine::IsOpSupported(param.opType)) {
589	        CHK_RET(SelectorEngine::Global()->Run(comm, param, topoInfo.get(), algName));
590	    } else {
591	        std::shared_ptr<ExecuteSelector> collAlgSelector = std::make_shared<ExecuteSelector>(ExecuteSelector());
592	        CHK_RET(collAlgSelector->Run(param, topoInfo.get(), algName));
593	    }
594	    if (algName == "") {
595	        HCCL_ERROR("[ReSelector] select algname fail!");
596	        return HCCL_E_PTR;
597	    }
598	    CHK_RET(SetCommEngine(param));
599	    // AIV_ONLY 模式下禁止回退到非 AIV 引擎，未选中 AIV 时直接返回不支持。
600	    if (param.commOpExpansionMode == HcclOpExpansionMode::HCCL_OP_EXPANSION_AIV_ONLY
601	        && param.engine != CommEngine::COMM_ENGINE_AIV) {
602	        HCCL_ERROR(
603	            "[HcclExecOp] opType[%d] currently do not select aiv mode, aiv only not support.",
604	            static_cast<int>(param.opType));
605	        return HCCL_E_NOT_SUPPORT;
606	    }
607	    // 如果一开始读取到的Engine不是aicpu，经过算法选择后回退到aicpu，则需要重新LoadAICPUKernel
608	    if ((param.engine == CommEngine::COMM_ENGINE_AICPU_TS) || (param.engine == CommEngine::COMM_ENGINE_CPU)) {
609	        HCCL_DEBUG("[ReSelector] is aicpu mode");
610	        CHK_RET(LoadAICPUKernel()); // 该函数内部有防止重复加载的逻辑
611	    }
612	    CHK_RET(SetOpParamAlgTag(param, algName));
613	    HCCL_INFO("Success to execute ReSelector.");
614	    return HCCL_SUCCESS;
